where id = #{videoId}
and like_count > 0

mapper.select:
select id as videoId, cover_url as coverUrl, play_url as playUrl, like_count as likeCount, status
from video
where user_id = #{userId}

select v.id as videoId, v.user_id as userId, u.nickname as nickName, u.avatar_url, v.category_id as categoryId, v.title, v.play_url as playUrl, v.cover_url as coverUrl, v.duration, v.like_count as likeCount, if(vl.video_id is not null, true, false) as isLiked, if(f.id is not null, true, false) as isFollowed, v.comment_count as commentCount, v.share_count as shareCount, v.created_time as createdTime
from video v
left join user_high u on v.user_id = u.id
left join video_like vl on v.id = vl.video_id and vl.user_id = #{userId}
left join follow f on v.user_id = f.followee_id and f.follower_id = #{userId}
where v.id < #{lastId} and  v.status = 1
order by v.id desc
limit #{size}

select v.id as videoId, v.user_id as userId, u.nickname as nickName, u.avatar_url as avatarUrl, v.category_id as categoryId, v.title, v.play_url as playUrl, v.cover_url as coverUrl, v.duration, v.like_count as likeCount, if(vl.video_id is not null, true, false) as isLiked, if(f.id is not null, true, false) as isFollowed, v.comment_count as commentCount, v.share_count as shareCount, v.created_time as createdTime
from video v
left join user_high u on v.user_id = u.id
left join video_like vl on v.id = vl.video_id and vl.user_id = #{userId}
